'From Squeak6.1 of 30 August 2026 [latest update: #23979] on 12 October 2026 at 9:01:32 pm'!!MCPackageManager class methodsFor: 'testing' stamp: 'ct 10/12/2026 20:55'!hasPackageNamed: aString 	^ self registry anySatisfy:		[ : each | each packageName = aString ]! !!PreferenceWizardMorph methodsFor: 'initialization - building' stamp: 'ct 10/12/2026 21:01'!createOneWayCheckbox: label for: selector help: terms	| checkbox |	self flag: #moveUpstream.	checkbox := self createCheckbox: label for: selector help: terms.	(self getCheckboxState: checkbox) ifTrue: [		self setCheckbox: checkbox enabled: false.		self setBalloonText: (checkbox balloonText ifNotNil: [:t | t , String cr , String cr] ifNil: ['']) , 'This package is already installed.' translated for: checkbox].	^ checkbox! !!PreferenceWizardMorph methodsFor: 'initialization - building' stamp: 'ct 10/12/2026 20:51'!getCheckboxState: checkbox	^ checkbox firstSubmorph getModelState! !!PreferenceWizardMorph methodsFor: 'initialization - building' stamp: 'ct 10/12/2026 20:52'!setButton: aMorph enabled: aBoolean	aMorph enabled: aBoolean.! !!PreferenceWizardMorph methodsFor: 'initialization - building' stamp: 'ct 10/12/2026 20:49'!setCheckbox: checkbox enabled: aBoolean	self setButton: checkbox firstSubmorph enabled: aBoolean.	self setLabel: checkbox submorphs second enabled: aBoolean.! !!PreferenceWizardMorph methodsFor: 'initialization - building' stamp: 'ct 10/12/2026 20:53'!setLabel: aMorph enabled: aBoolean	aMorph newContents:		(aMorph contents copy			addAttribute: (TextColor color: (self defaultTextColor adjustBrightness: (aBoolean ifTrue: [-0.15] ifFalse: [-0.3])));			yourself).! !!PreferenceWizardMorph methodsFor: 'initialization - pages' stamp: 'ct 10/12/2026 20:53'!initializePage99ExtraPackages	"Let the user install extra packages."	| currentPage packagesList installButton |	currentPage := self createPage.	currentPage		cellPositioning: #topCenter;		addMorphBack: self createHorizontalSpacer;		addMorphBack: ((self createLabel: 'Do you want to install extra packages?' translated color: Color white)			hResizing: #shrinkWrap;			averageLineLength: 65;			yourself);		addMorphBack: ((self createLabel: 'Note that the installation process requires a network connection with Internet access and might take several minutes.' translated color: (Color gray: 0.9))			hResizing: #shrinkWrap;			averageLineLength: 65;			yourself).		currentPage submorphs last text addAttribute: TextAlignment centered.	currentPage submorphs last layoutChanged.		currentPage addMorphBack: (self createVerticalSpace height: self layoutInset).		packagesList := self createScrollPane.	packagesList		width: (self defaultTextStyle compositionWidthFor: 65);		hResizing: #rigid;		vResizing: #spaceFill.	packagesList scroller firstSubmorph addAllMorphsBack: {		self createCheckbox: 'Latest system updates' translated for: #InstallLatestUpdates help: 'Install the latest patches for ' translated, SystemVersion current version.		self createOneWayCheckbox: 'Refactoring support in code browsers' translated for: #InstallRefactoringTools help: 'Refactoring is a process of re-writing or re-organizing text or code. The purpose of a refactor is to make the code or text more understandable and readable while exactly preserving its meaning and behavior' translated.		self createOneWayCheckbox: 'Autocomplete in code editors' translated for: #InstallAutoComplete help: 'Package that provides interactive, context-sensitive auto-completion for Squeak' translated.		self createOneWayCheckbox: 'Git support and browser' translated for: #InstallGitInfrastructure help: 'From the Git Browser, you can create new commits, synchronize with remote repositories (fetch, pull, push), manage and merge branches, switch between them, and compare different versions' translated.		self createOneWayCheckbox: 'Foreign function interface (FFI)' translated for: #InstallFFI help: 'FFI, the Squeak Foreign Function Interface, is used to call functions located in shared libraries that are not part of the Squeak VM nor its plugins' translated.		self createOneWayCheckbox: 'Access OS functions' translated for: #InstallOSProcess help: 'OSProcess provides access to operating system functions, including pipes and child process creation' translated.		self createOneWayCheckbox: 'Integrate Squeak''s mailing lists' translated for: #InstallSqueakInboxTalk help: 'Through Squeak Inbox Talk, you can engage with our community from within Squeak using tools that integrate our mailing lists such as squeak-dev and vm-dev' translated.		"self createOneWayCheckbox: 'Compatibility packages for legacy apps' translated for: #InstallCompatibilityPackages help: 'Install protocols (i.e., classes and methods) that got deprecated for this version to make older applications work without changes.' translated."	}.			currentPage addMorphBack: packagesList.	currentPage addMorphBack: ((self createLabel: 'Find more on www.squeak.org/projects' color: (Color gray: 0.9))		hResizing: #shrinkWrap; yourself).		installButton := self createButton		action: #installExtraPackagesVia:;		label: 'Yes, install selected packages.' translated;		yourself.	installButton		setProperty: #label toValue: installButton label;		arguments: {installButton}.		currentPage addMorphBack: installButton.	currentPage addMorphBack: (self createButton action: #showSqueak; label: 'No, maybe later.' translated).		^ currentPage! !!PreferenceWizardMorph methodsFor: 'actions - packages' stamp: 'ct 10/12/2026 20:56'!stateInstallAutoComplete	^ self		valueOfProperty: #InstallAutoComplete		ifAbsent: [MCWorkingCopy hasPackageNamed: "'OCompletion'"'Autocompletion']! !!PreferenceWizardMorph methodsFor: 'actions - packages' stamp: 'ct 10/12/2026 20:56'!stateInstallFFI	^ self		valueOfProperty: #InstallFFI		ifAbsent: [MCWorkingCopy hasPackageNamed: 'FFI-Kernel']! !!PreferenceWizardMorph methodsFor: 'actions - packages' stamp: 'ct 10/12/2026 20:56'!stateInstallGitInfrastructure	^ self		valueOfProperty: #InstallGitInfrastructure		ifAbsent: ["false"true]! !!PreferenceWizardMorph methodsFor: 'actions - packages' stamp: 'ct 10/12/2026 20:57'!stateInstallOSProcess	^ self		valueOfProperty: #InstallOSProcess		ifAbsent: [MCWorkingCopy hasPackageNamed: 'OSProcess']! !!PreferenceWizardMorph methodsFor: 'actions - packages' stamp: 'ct 10/12/2026 20:57'!stateInstallRefactoringTools	^ self		valueOfProperty: #InstallRefactoringTools		ifAbsent: [MCWorkingCopy hasPackageNamed: 'RefactoringTools']! !!PreferenceWizardMorph methodsFor: 'actions - packages' stamp: 'ct 10/12/2026 20:57'!stateInstallSqueakInboxTalk	^ self		valueOfProperty: #InstallSqueakInboxTalk		ifAbsent: [MCWorkingCopy hasPackageNamed: 'SqueakInboxTalk']! !!MCPackageManager class reorganize!('system changes' classModified: classMoved: classRemoved: methodModified: methodMoved: methodRemoved: protocolRenamed: systemCategoryRenamed:)('private' allManagers registry)('instance creation' forPackage: forPackageNamed:)('class initialization' initialize)('system changes - support' isExtensionCategory: managersForCategory:do: managersForClass:category:do: managersForClass:do: managersForClass:selector:do: managersForExtensionCategory:do: registerForNotifications reregisterForNotificationsWith:)('testing' hasPackageNamed:)!